<?php require __DIR__.'/admin-catalog.php'; ?>
<section><h2>Client nou</h2><p>Planul este acordat manual, fără abonament sau încasare Stripe. Clientul își confirmă emailul, parola inițială și termenii înainte de activare.</p><form method="post" class="grid"><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><input type="hidden" name="action" value="create"><label>Nume<input name="name" required minlength="2" maxlength="150" autocomplete="off"></label><label>Email<input name="email" type="email" required maxlength="254" autocomplete="off"></label><label>Parolă inițială<input name="password" type="password" required minlength="12" maxlength="200" autocomplete="new-password"></label><label>Plan<select name="plan"><?php foreach($plans as $p): ?><option value="<?= e($p['slug']) ?>"><?= e($p['name'].' · '.$p['capacity']) ?></option><?php endforeach ?></select></label><label>Limbă<select name="locale"><?php foreach(['ro','en','fr','de'] as $l): ?><option><?= e($l) ?></option><?php endforeach ?></select></label><button>Creează client</button></form></section>
<section><h2>Clienți</h2><form method="get" class="search"><label>Caută după nume sau email<input name="q" value="<?= e($search) ?>" maxlength="254"></label><button>Caută</button></form><p>Maximum 100 rezultate. Pentru abonamentele active, schimbarea manuală actualizează tariful Stripe de la următoarea reînnoire, fără plată sau refund acum. Downgrade-ul necesită ca fișierele să încapă în noua cotă. Ban-ul păstrează abonamentul și fișierele.</p>
<div class="table"><table><thead><tr><th>Client</th><th>Plan și stare</th><th>Schimbă planul</th><th>Suspendare</th></tr></thead><tbody>
<?php foreach($clients as $u): ?><tr><td><strong><?= e($u['name']) ?></strong><br><?= e($u['email']) ?><br><small><?= $u['email_verified_at']?'Email confirmat':'Email neconfirmat' ?></small></td><td><?= e($u['selected_plan_id']) ?> · <?= e($u['status']) ?><br><?= $u['manual_plan']?'Acordat manual':e($u['subscription_status']??'Fără abonament') ?><?php if($u['renewal_at']): ?><br>Reînnoire: <?= e(date('d.m.Y H:i',(int)$u['renewal_at'])) ?> UTC<?php endif ?><br><small>Protecție: <?= e($u['access_sync']??'ready') ?></small></td><td><form method="post"><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><input type="hidden" name="user_id" value="<?= e($u['id']) ?>"><input type="hidden" name="action" value="plan"><label>Plan pentru <?= e($u['email']) ?><select name="plan"><?php foreach($plans as $p): ?><option value="<?= e($p['slug']) ?>" <?= $p['slug']===$u['selected_plan_id']?'selected':'' ?>><?= e($p['capacity']) ?></option><?php endforeach ?></select></label><label>Motiv<input name="reason" required minlength="3" maxlength="500"></label><button>Aplică planul</button></form></td><td><form method="post"><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><input type="hidden" name="user_id" value="<?= e($u['id']) ?>"><label>Motiv<input name="reason" required minlength="3" maxlength="500"></label><button name="action" value="<?= $u['banned_at']?'unban':'ban' ?>"><?= $u['banned_at']?'Ridică suspendarea':'Suspendă contul' ?></button><?php if($u['banned_at']): ?><p><?= e($u['reason']) ?></p><button name="action" value="ban" class="secondary">Reîncearcă suspendarea</button><?php endif ?></form></td></tr><?php endforeach ?>
<?php if(!$clients): ?><tr><td colspan="4">Niciun client găsit.</td></tr><?php endif ?></tbody></table></div></section>
<?php foreach($clients as $u): if(($u['quota_sync']??'ready')==='ready')continue; ?><section><h2>Sincronizare cotă în așteptare</h2><p><?= e($u['email']) ?> · <?= e($u['selected_plan_id']) ?></p><form method="post"><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><input type="hidden" name="user_id" value="<?= e($u['id']) ?>"><button name="action" value="sync">Reîncearcă sincronizarea cotei</button></form></section><?php endforeach ?>
<section><h2>Upgrade-uri și schimbări de plan</h2><p>Reîncercarea verifică plata existentă și sincronizează planul; nu încasează din nou. Anularea este disponibilă numai înainte de confirmarea plății.</p><div class="table"><table><thead><tr><th>Client</th><th>Schimbare</th><th>Plată / stare</th><th>Acțiuni</th></tr></thead><tbody>
<?php foreach($changes as $r): ?><tr><td><?= e($r['email']) ?><br><small><?= e($r['id']) ?></small></td><td><?= e($r['from_plan'].' → '.$r['to_plan']) ?><br><?= e($r['kind']) ?></td><td><?= e(number_format($r['amount']/100,2,',','').' '.strtoupper($r['currency'])) ?><br><?= e($r['status']) ?><br><?= e($r['error_code']) ?><?php if($r['paid_at']): ?><br>Plată confirmată<?php endif ?></td><td><?php if(!in_array($r['status'],['completed','cancelled','expired'],true)): ?><form method="post"><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><input type="hidden" name="change_id" value="<?= e($r['id']) ?>"><button name="action" value="retry">Reîncearcă</button><?php if(in_array($r['status'],['creating','pending'],true)): ?><button class="secondary" name="action" value="cancel">Anulează plata neconfirmată</button><?php endif ?></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section>
<section><h2>Jurnal administrare</h2><div class="table"><table><thead><tr><th>Data UTC</th><th>Administrator / client</th><th>Acțiune</th></tr></thead><tbody><?php foreach($audit as $a): ?><tr><td><?= e(date('d.m.Y H:i',$a['created_at'])) ?></td><td><?= e($a['admin_email']) ?><br><?= e($a['customer_email']) ?></td><td><?= e($a['action']) ?><br><?= e($a['detail']) ?></td></tr><?php endforeach ?></tbody></table></div></section>
<?php endif ?></main></body></html>
